-- Finance F6-3 (docs/finance-billing-f6.md §10): payment reminder policies, customer assignments,
-- holds and the reminder record. Generated by `prisma migrate diff`, then the constraints, guards,
-- grants and RLS Prisma cannot express were added by hand (section marked "hand-written"). Wrapped in
-- one transaction (docs/migration-readiness.md §7, STAB-M6).
--
-- Ordering: depends on 20261115000000_finance (finance_documents, FinanceDocumentKind), customers and
-- 20261126000000_finance_billing (the audit_finance_system_write policy, reused unchanged for the
-- reminder worker's finance.system.* events). It changes no existing table or row; it adds four
-- tables. Privileged SQL: prisma/privileged/003_finance_reminders_due.sql (the reminder worker's
-- due-business function) must be applied after this migration with `pnpm db:privileged`.
--
-- Nothing here sends mail. A reminder stops at READY until Communications C2-C provides an outbox;
-- no state ever means "delivered" (D-F6-8, D-C2-13).
--
-- SQLSTATEs (class FN, finance): FN040 policy identity fixed, invalid policy transition or stages,
-- FN041 customer assignment refused, FN042 hold refused or fixed, FN043 reminder identity fixed or
-- invalid reminder transition, FN044 a reminder or hold does not match its invoice, FN045 invalid
-- outbound state transition.
BEGIN;
-- CreateTable
CREATE TABLE "finance_reminder_policies" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE',
    "is_default" BOOLEAN NOT NULL DEFAULT false,
    "stages" JSONB NOT NULL,
    "last_planned_at" TIMESTAMPTZ,
    "archived_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_by_id" UUID,
    "updated_by_id" UUID,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "finance_reminder_policies_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "finance_reminder_customer_policies" (
    "business_id" UUID NOT NULL,
    "customer_id" UUID NOT NULL,
    "policy_id" UUID,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_by_id" UUID,
    "updated_by_id" UUID,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "finance_reminder_customer_policies_pkey" PRIMARY KEY ("business_id","customer_id")
);

-- CreateTable
CREATE TABLE "finance_reminder_holds" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "scope" TEXT NOT NULL,
    "customer_id" UUID NOT NULL,
    "invoice_id" UUID,
    "invoice_kind" "FinanceDocumentKind" NOT NULL DEFAULT 'INVOICE',
    "reason" TEXT NOT NULL,
    "note" TEXT,
    "until_date" DATE,
    "released_at" TIMESTAMPTZ,
    "released_by_id" UUID,
    "created_by_id" UUID NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "finance_reminder_holds_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "finance_reminders" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "invoice_id" UUID NOT NULL,
    "invoice_kind" "FinanceDocumentKind" NOT NULL DEFAULT 'INVOICE',
    "customer_id" UUID NOT NULL,
    "policy_id" UUID NOT NULL,
    "policy_version" INTEGER NOT NULL,
    "offset_days" SMALLINT NOT NULL,
    "stage_label" TEXT NOT NULL,
    "due_date" DATE NOT NULL,
    "scheduled_on" DATE NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'PENDING',
    "attempts" SMALLINT NOT NULL DEFAULT 0,
    "max_attempts" SMALLINT NOT NULL DEFAULT 5,
    "run_after" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "lease_id" UUID,
    "lease_expires_at" TIMESTAMPTZ,
    "outcome_code" TEXT,
    "checked_outstanding" DECIMAL(18,4),
    "checked_at" TIMESTAMPTZ,
    "outbound_id" UUID,
    "outbound_state" TEXT,
    "ready_at" TIMESTAMPTZ,
    "queued_at" TIMESTAMPTZ,
    "finished_at" TIMESTAMPTZ,
    "dismissed_by_id" UUID,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "finance_reminders_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "finance_reminder_policies_business_id_status_created_at_id_idx" ON "finance_reminder_policies"("business_id", "status", "created_at" DESC, "id");

-- CreateIndex
CREATE UNIQUE INDEX "finance_reminder_policies_business_id_id_key" ON "finance_reminder_policies"("business_id", "id");

-- CreateIndex
CREATE INDEX "finance_reminder_customer_policies_business_id_policy_id_idx" ON "finance_reminder_customer_policies"("business_id", "policy_id");

-- CreateIndex
CREATE INDEX "finance_reminder_holds_business_id_customer_id_released_at_idx" ON "finance_reminder_holds"("business_id", "customer_id", "released_at");

-- CreateIndex
CREATE INDEX "finance_reminder_holds_business_id_invoice_id_idx" ON "finance_reminder_holds"("business_id", "invoice_id");

-- CreateIndex
CREATE INDEX "finance_reminder_holds_business_id_created_at_id_idx" ON "finance_reminder_holds"("business_id", "created_at" DESC, "id");

-- CreateIndex
CREATE UNIQUE INDEX "finance_reminder_holds_business_id_id_key" ON "finance_reminder_holds"("business_id", "id");

-- CreateIndex
CREATE INDEX "finance_reminders_business_id_status_run_after_idx" ON "finance_reminders"("business_id", "status", "run_after");

-- CreateIndex
CREATE INDEX "finance_reminders_business_id_customer_id_created_at_idx" ON "finance_reminders"("business_id", "customer_id", "created_at" DESC);

-- CreateIndex
CREATE INDEX "finance_reminders_business_id_created_at_id_idx" ON "finance_reminders"("business_id", "created_at" DESC, "id");

-- CreateIndex
CREATE UNIQUE INDEX "finance_reminders_business_id_id_key" ON "finance_reminders"("business_id", "id");

-- CreateIndex
CREATE UNIQUE INDEX "finance_reminders_business_id_invoice_id_offset_days_key" ON "finance_reminders"("business_id", "invoice_id", "offset_days");

-- CreateIndex
CREATE UNIQUE INDEX "finance_reminders_business_id_outbound_id_key" ON "finance_reminders"("business_id", "outbound_id");

-- AddForeignKey
ALTER TABLE "finance_reminder_policies" ADD CONSTRAINT "finance_reminder_policies_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "finance_reminder_customer_policies" ADD CONSTRAINT "finance_reminder_customer_policies_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "finance_reminder_customer_policies" ADD CONSTRAINT "finance_reminder_customer_policies_customer_fkey" FOREIGN KEY ("business_id", "customer_id") REFERENCES "customers"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "finance_reminder_customer_policies" ADD CONSTRAINT "finance_reminder_customer_policies_policy_fkey" FOREIGN KEY ("business_id", "policy_id") REFERENCES "finance_reminder_policies"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "finance_reminder_holds" ADD CONSTRAINT "finance_reminder_holds_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "finance_reminder_holds" ADD CONSTRAINT "finance_reminder_holds_customer_fkey" FOREIGN KEY ("business_id", "customer_id") REFERENCES "customers"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

