ALTER TABLE "finance_reminder_holds" ADD CONSTRAINT "finance_reminder_holds_invoice_fkey" FOREIGN KEY ("business_id", "invoice_id", "invoice_kind") REFERENCES "finance_documents"("business_id", "id", "kind") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "finance_reminders" ADD CONSTRAINT "finance_reminders_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "finance_reminders" ADD CONSTRAINT "finance_reminders_invoice_fkey" FOREIGN KEY ("business_id", "invoice_id", "invoice_kind") REFERENCES "finance_documents"("business_id", "id", "kind") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "finance_reminders" ADD CONSTRAINT "finance_reminders_customer_fkey" FOREIGN KEY ("business_id", "customer_id") REFERENCES "customers"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "finance_reminders" ADD CONSTRAINT "finance_reminders_policy_fkey" FOREIGN KEY ("business_id", "policy_id") REFERENCES "finance_reminder_policies"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;




-- =============================================================================================
-- Hand-written: constraints, guards, grants and RLS.
-- =============================================================================================

-- ---- stages ------------------------------------------------------------------------------------
-- [{ "offsetDays": -60..365, "label": 1..80 characters }], 1 to 8 stages, offsets strictly
-- increasing. Immutable, so it can back a CHECK constraint.
CREATE FUNCTION finance_reminder_stages_valid(p_stages jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  s jsonb;
  prev integer := NULL;
  o integer;
BEGIN
  IF p_stages IS NULL OR jsonb_typeof(p_stages) <> 'array' OR jsonb_array_length(p_stages) NOT BETWEEN 1 AND 8 THEN
    RETURN false;
  END IF;
  FOR s IN SELECT value FROM jsonb_array_elements(p_stages) LOOP
    IF jsonb_typeof(s) <> 'object' OR (SELECT count(*) FROM jsonb_object_keys(s)) <> 2
       OR jsonb_typeof(s -> 'offsetDays') <> 'number' OR jsonb_typeof(s -> 'label') <> 'string' THEN
      RETURN false;
    END IF;
    IF (s ->> 'offsetDays') !~ '^-?[0-9]{1,3}$' THEN RETURN false; END IF;
    o := (s ->> 'offsetDays')::integer;
    IF o NOT BETWEEN -60 AND 365 OR (prev IS NOT NULL AND o <= prev) THEN RETURN false; END IF;
    IF char_length(s ->> 'label') NOT BETWEEN 1 AND 80 THEN RETURN false; END IF;
    prev := o;
  END LOOP;
  RETURN true;
END $$;

-- ---- finance_reminder_policies -----------------------------------------------------------------
ALTER TABLE "finance_reminder_policies"
  ADD CONSTRAINT finance_reminder_policies_name_length CHECK (char_length("name") BETWEEN 1 AND 200),
  ADD CONSTRAINT finance_reminder_policies_status_values CHECK ("status" IN ('ACTIVE', 'ARCHIVED')),
  ADD CONSTRAINT finance_reminder_policies_archived_pair CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL)),
  -- Only an active policy can be the default.
  ADD CONSTRAINT finance_reminder_policies_default_active CHECK (NOT "is_default" OR "status" = 'ACTIVE'),
  ADD CONSTRAINT finance_reminder_policies_stages_valid CHECK (finance_reminder_stages_valid("stages")),
  ADD CONSTRAINT finance_reminder_policies_version_positive CHECK ("version" >= 1);
-- At most one default per business.
CREATE UNIQUE INDEX "finance_reminder_policies_default_key" ON "finance_reminder_policies" ("business_id") WHERE "is_default";

CREATE FUNCTION finance_reminder_policies_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'ACTIVE' THEN
      RAISE EXCEPTION 'a reminder policy starts active' USING ERRCODE = 'FN040';
    END IF;
    NEW.archived_at := NULL; NEW.last_planned_at := NULL; NEW.version := 1;
    NEW.created_at := now(); NEW.updated_at := now();
    RETURN NEW;
  END IF;
  IF (NEW.id, NEW.business_id, NEW.created_at, NEW.created_by_id) IS DISTINCT FROM (OLD.id, OLD.business_id, OLD.created_at, OLD.created_by_id) THEN
    RAISE EXCEPTION 'reminder policy identity is fixed' USING ERRCODE = 'FN040';
  END IF;
  IF OLD.status = 'ARCHIVED' THEN
    RAISE EXCEPTION 'an archived reminder policy is final' USING ERRCODE = 'FN040';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    NEW.archived_at := now();
  ELSE
    NEW.archived_at := OLD.archived_at;
  END IF;
  -- The worker's planning stamp alone is not an edit.
  IF (NEW.name, NEW.status, NEW.is_default, NEW.stages, NEW.version, NEW.updated_by_id)
     IS NOT DISTINCT FROM (OLD.name, OLD.status, OLD.is_default, OLD.stages, OLD.version, OLD.updated_by_id) THEN
    NEW.updated_at := OLD.updated_at;
  ELSE
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER finance_reminder_policies_guard BEFORE INSERT OR UPDATE ON "finance_reminder_policies"
  FOR EACH ROW EXECUTE FUNCTION finance_reminder_policies_guard();

-- ---- finance_reminder_customer_policies --------------------------------------------------------
ALTER TABLE "finance_reminder_customer_policies"
  ADD CONSTRAINT finance_reminder_customer_policies_version_positive CHECK ("version" >= 1);

CREATE FUNCTION finance_reminder_customer_policies_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  p_status text;
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.business_id, NEW.customer_id, NEW.created_at, NEW.created_by_id)
     IS DISTINCT FROM (OLD.business_id, OLD.customer_id, OLD.created_at, OLD.created_by_id) THEN
    RAISE EXCEPTION 'customer reminder assignment identity is fixed' USING ERRCODE = 'FN041';
  END IF;
  -- A customer can be assigned only an active policy (an archived one later simply stops applying).
  IF NEW.policy_id IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.policy_id IS DISTINCT FROM OLD.policy_id) THEN
    SELECT "status" INTO p_status FROM "finance_reminder_policies" WHERE "business_id" = NEW.business_id AND "id" = NEW.policy_id;
    IF p_status IS DISTINCT FROM 'ACTIVE' THEN
      RAISE EXCEPTION 'a customer can be assigned an active reminder policy only' USING ERRCODE = 'FN041';
    END IF;
  END IF;
  IF TG_OP = 'INSERT' THEN NEW.created_at := now(); NEW.version := 1; END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;
CREATE TRIGGER finance_reminder_customer_policies_guard BEFORE INSERT OR UPDATE ON "finance_reminder_customer_policies"
  FOR EACH ROW EXECUTE FUNCTION finance_reminder_customer_policies_guard();

-- ---- finance_reminder_holds --------------------------------------------------------------------
ALTER TABLE "finance_reminder_holds"
  ADD CONSTRAINT finance_reminder_holds_scope_values CHECK ("scope" IN ('CUSTOMER', 'INVOICE')),
  ADD CONSTRAINT finance_reminder_holds_scope_pair CHECK (("scope" = 'INVOICE') = ("invoice_id" IS NOT NULL)),
  ADD CONSTRAINT finance_reminder_holds_invoice_kind CHECK ("invoice_kind" = 'INVOICE'),
  ADD CONSTRAINT finance_reminder_holds_reason_values CHECK ("reason" IN ('DISPUTE', 'PAYMENT_PLAN', 'CUSTOMER_REQUEST', 'OTHER')),
  ADD CONSTRAINT finance_reminder_holds_note_length CHECK ("note" IS NULL OR char_length("note") BETWEEN 1 AND 1000),
  ADD CONSTRAINT finance_reminder_holds_released_pair CHECK (("released_at" IS NULL) = ("released_by_id" IS NULL));

CREATE FUNCTION finance_reminder_holds_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  d record;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.released_at IS NOT NULL OR NEW.released_by_id IS NOT NULL THEN
      RAISE EXCEPTION 'a hold starts in effect' USING ERRCODE = 'FN042';
    END IF;
    IF NEW.invoice_id IS NOT NULL THEN
      SELECT "customer_id", "kind", "status" INTO d FROM "finance_documents" WHERE "business_id" = NEW.business_id AND "id" = NEW.invoice_id;
      IF d IS NULL OR d.kind <> 'INVOICE' OR d.status <> 'ISSUED' OR d.customer_id <> NEW.customer_id THEN
        RAISE EXCEPTION 'a hold is on an issued invoice of its customer' USING ERRCODE = 'FN044';
      END IF;
    END IF;
    NEW.created_at := now(); NEW.updated_at := now();
    RETURN NEW;
  END IF;
  -- Everything is fixed except the release, which is recorded once.
  IF (NEW.id, NEW.business_id, NEW.scope, NEW.customer_id, NEW.invoice_id, NEW.invoice_kind, NEW.reason, NEW.note, NEW.until_date, NEW.created_by_id, NEW.created_at)
     IS DISTINCT FROM (OLD.id, OLD.business_id, OLD.scope, OLD.customer_id, OLD.invoice_id, OLD.invoice_kind, OLD.reason, OLD.note, OLD.until_date, OLD.created_by_id, OLD.created_at) THEN
    RAISE EXCEPTION 'a hold is fixed; release it and place a new one' USING ERRCODE = 'FN042';
  END IF;
  IF OLD.released_at IS NOT NULL THEN
    RAISE EXCEPTION 'a released hold is final' USING ERRCODE = 'FN042';
  END IF;
  IF NEW.released_by_id IS NOT NULL THEN NEW.released_at := now(); END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;
CREATE TRIGGER finance_reminder_holds_guard BEFORE INSERT OR UPDATE ON "finance_reminder_holds"
  FOR EACH ROW EXECUTE FUNCTION finance_reminder_holds_guard();

-- ---- finance_reminders -------------------------------------------------------------------------
ALTER TABLE "finance_reminders"
  ADD CONSTRAINT finance_reminders_status_values CHECK ("status" IN ('PENDING', 'RUNNING', 'READY', 'QUEUED', 'SKIPPED', 'FAILED')),
  ADD CONSTRAINT finance_reminders_invoice_kind CHECK ("invoice_kind" = 'INVOICE'),
  ADD CONSTRAINT finance_reminders_offset_range CHECK ("offset_days" BETWEEN -60 AND 365),
  ADD CONSTRAINT finance_reminders_label_length CHECK (char_length("stage_label") BETWEEN 1 AND 80),
  ADD CONSTRAINT finance_reminders_schedule CHECK ("scheduled_on" = "due_date" + "offset_days"),
  ADD CONSTRAINT finance_reminders_policy_version CHECK ("policy_version" >= 1),
  ADD CONSTRAINT finance_reminders_attempts_range CHECK ("attempts" >= 0 AND "max_attempts" BETWEEN 1 AND 50 AND "attempts" <= "max_attempts"),
  -- A running reminder always holds a lease; nothing else does.
  ADD CONSTRAINT finance_reminders_lease_running CHECK ((("status" = 'RUNNING') = ("lease_id" IS NOT NULL)) AND (("lease_id" IS NULL) = ("lease_expires_at" IS NULL))),
  ADD CONSTRAINT finance_reminders_finished_pair CHECK (("status" IN ('SKIPPED', 'FAILED')) = ("finished_at" IS NOT NULL)),
  -- A skipped or failed reminder always says why, as a stable code, never as text.
  ADD CONSTRAINT finance_reminders_outcome_needed CHECK ("status" NOT IN ('SKIPPED', 'FAILED') OR "outcome_code" IS NOT NULL),
  ADD CONSTRAINT finance_reminders_outcome_format CHECK ("outcome_code" IS NULL OR "outcome_code" ~ '^[a-z][a-z_]{1,48}$'),
  ADD CONSTRAINT finance_reminders_ready_checked CHECK ("status" NOT IN ('READY', 'QUEUED') OR ("checked_at" IS NOT NULL AND "checked_outstanding" > 0)),
  -- Handed over to C2-C exactly when it has an outbound message; never a "delivered" state.
  ADD CONSTRAINT finance_reminders_outbound_pair CHECK (("outbound_id" IS NULL) = ("outbound_state" IS NULL) AND ("outbound_id" IS NULL) = ("queued_at" IS NULL)),
  ADD CONSTRAINT finance_reminders_outbound_status CHECK (("status" = 'QUEUED') <= ("outbound_id" IS NOT NULL) AND ("outbound_id" IS NULL OR "status" IN ('QUEUED', 'SKIPPED'))),
  ADD CONSTRAINT finance_reminders_outbound_values CHECK ("outbound_state" IS NULL OR "outbound_state" IN ('QUEUED', 'SENDING', 'SUBMITTED', 'ACCEPTED', 'FAILED', 'UNKNOWN', 'BOUNCED')),
  ADD CONSTRAINT finance_reminders_dismissed CHECK ("dismissed_by_id" IS NULL OR ("status" = 'SKIPPED' AND "outcome_code" = 'dismissed'));

CREATE FUNCTION finance_reminders_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  d record;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'PENDING' OR NEW.attempts <> 0 OR NEW.outbound_id IS NOT NULL OR NEW.lease_id IS NOT NULL OR NEW.dismissed_by_id IS NOT NULL THEN
      RAISE EXCEPTION 'a reminder starts pending' USING ERRCODE = 'FN043';
    END IF;
    SELECT "customer_id", "kind", "status", "due_date" INTO d FROM "finance_documents" WHERE "business_id" = NEW.business_id AND "id" = NEW.invoice_id;
    IF d IS NULL OR d.kind <> 'INVOICE' OR d.status <> 'ISSUED' OR d.customer_id <> NEW.customer_id OR d.due_date IS DISTINCT FROM NEW.due_date THEN
      RAISE EXCEPTION 'a reminder is for an issued invoice of its customer, on its due date' USING ERRCODE = 'FN044';
    END IF;
    NEW.ready_at := NULL; NEW.queued_at := NULL; NEW.finished_at := NULL; NEW.checked_at := NULL; NEW.checked_outstanding := NULL;
    NEW.created_at := now(); NEW.updated_at := now();
    RETURN NEW;
  END IF;
  IF (NEW.id, NEW.business_id, NEW.invoice_id, NEW.invoice_kind, NEW.customer_id, NEW.policy_id, NEW.policy_version, NEW.offset_days, NEW.stage_label,
      NEW.due_date, NEW.scheduled_on, NEW.created_at)
     IS DISTINCT FROM (OLD.id, OLD.business_id, OLD.invoice_id, OLD.invoice_kind, OLD.customer_id, OLD.policy_id, OLD.policy_version, OLD.offset_days, OLD.stage_label,
      OLD.due_date, OLD.scheduled_on, OLD.created_at) THEN
    RAISE EXCEPTION 'reminder identity is fixed' USING ERRCODE = 'FN043';
  END IF;
  IF OLD.status IN ('SKIPPED', 'FAILED') THEN
    RAISE EXCEPTION 'skipped and failed reminders are final' USING ERRCODE = 'FN043';
  END IF;
  IF NOT ((OLD.status = 'PENDING' AND NEW.status IN ('PENDING', 'RUNNING', 'SKIPPED'))
       OR (OLD.status = 'RUNNING' AND NEW.status IN ('RUNNING', 'PENDING', 'READY', 'QUEUED', 'SKIPPED', 'FAILED'))
       OR (OLD.status = 'READY' AND NEW.status IN ('READY', 'RUNNING', 'SKIPPED'))
       -- Once handed over, only C2-C's pre-send check can still stop it, and only before sending starts.
       OR (OLD.status = 'QUEUED' AND (NEW.status = 'QUEUED' OR (NEW.status = 'SKIPPED' AND OLD.outbound_state = 'QUEUED')))) THEN
    RAISE EXCEPTION 'invalid reminder transition' USING ERRCODE = 'FN043';
  END IF;
  -- The outbound message is attached once, at hand-over (RUNNING → QUEUED), and never replaced.
  IF OLD.outbound_id IS NOT NULL AND NEW.outbound_id IS DISTINCT FROM OLD.outbound_id THEN
    RAISE EXCEPTION 'a reminder''s outbound message is fixed' USING ERRCODE = 'FN043';
  END IF;
  IF OLD.outbound_id IS NULL AND NEW.outbound_id IS NOT NULL AND NOT (OLD.status = 'RUNNING' AND NEW.status = 'QUEUED' AND NEW.outbound_state = 'QUEUED') THEN
    RAISE EXCEPTION 'a reminder is handed over from a running check only' USING ERRCODE = 'FN043';
  END IF;
  -- Outbound states follow C2's register: UNKNOWN is never turned into FAILED and nothing is "delivered".
  IF NEW.outbound_state IS DISTINCT FROM OLD.outbound_state AND OLD.outbound_state IS NOT NULL AND NOT (
       (OLD.outbound_state = 'QUEUED' AND NEW.outbound_state IN ('SENDING', 'SUBMITTED', 'ACCEPTED', 'FAILED', 'UNKNOWN'))
    OR (OLD.outbound_state = 'SENDING' AND NEW.outbound_state IN ('SUBMITTED', 'ACCEPTED', 'FAILED', 'UNKNOWN'))
    OR (OLD.outbound_state = 'SUBMITTED' AND NEW.outbound_state IN ('ACCEPTED', 'FAILED', 'UNKNOWN', 'BOUNCED'))
    OR (OLD.outbound_state = 'ACCEPTED' AND NEW.outbound_state = 'BOUNCED')
    OR (OLD.outbound_state = 'UNKNOWN' AND NEW.outbound_state IN ('ACCEPTED', 'BOUNCED'))) THEN
    RAISE EXCEPTION 'invalid outbound state transition' USING ERRCODE = 'FN045';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'READY' THEN NEW.ready_at := coalesce(OLD.ready_at, now()); ELSE NEW.ready_at := OLD.ready_at; END IF;
    IF NEW.status = 'QUEUED' THEN NEW.queued_at := now(); ELSE NEW.queued_at := OLD.queued_at; END IF;
    IF NEW.status IN ('SKIPPED', 'FAILED') THEN NEW.finished_at := now(); END IF;
  ELSE
    NEW.ready_at := OLD.ready_at; NEW.queued_at := OLD.queued_at; NEW.finished_at := OLD.finished_at;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;
CREATE TRIGGER finance_reminders_guard BEFORE INSERT OR UPDATE ON "finance_reminders"
  FOR EACH ROW EXECUTE FUNCTION finance_reminders_guard();

REVOKE ALL ON FUNCTION finance_reminder_policies_guard(), finance_reminder_customer_policies_guard(), finance_reminder_holds_guard(),
  finance_reminders_guard() FROM PUBLIC;

-- ---- least privilege ---------------------------------------------------------------------------
-- No DELETE anywhere: policies are archived, assignments point back to the default, holds are
-- released and reminders are skipped. All of them keep their history.
REVOKE ALL ON "finance_reminder_policies", "finance_reminder_customer_policies", "finance_reminder_holds", "finance_reminders" FROM bos_app;
GRANT SELECT, INSERT ON "finance_reminder_policies", "finance_reminder_customer_policies", "finance_reminder_holds", "finance_reminders" TO bos_app;
GRANT UPDATE ("name", "status", "is_default", "stages", "last_planned_at", "archived_at", "version", "updated_by_id", "updated_at")
  ON "finance_reminder_policies" TO bos_app;
GRANT UPDATE ("policy_id", "version", "updated_by_id", "updated_at") ON "finance_reminder_customer_policies" TO bos_app;
GRANT UPDATE ("released_at", "released_by_id", "updated_at") ON "finance_reminder_holds" TO bos_app;
GRANT UPDATE ("status", "attempts", "max_attempts", "run_after", "lease_id", "lease_expires_at", "outcome_code", "checked_outstanding", "checked_at",
              "outbound_id", "outbound_state", "ready_at", "queued_at", "finished_at", "dismissed_by_id", "updated_at")
  ON "finance_reminders" TO bos_app;

-- ---- row-level security --------------------------------------------------------------------------
ALTER TABLE "finance_reminder_policies" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "finance_reminder_policies" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "finance_reminder_policies" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

ALTER TABLE "finance_reminder_customer_policies" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "finance_reminder_customer_policies" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "finance_reminder_customer_policies" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

ALTER TABLE "finance_reminder_holds" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "finance_reminder_holds" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "finance_reminder_holds" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

ALTER TABLE "finance_reminders" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "finance_reminders" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "finance_reminders" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

COMMIT;
